// ▶ Paste these three from the staff area → Settings → Email, and Supabase → Project Settings → API.
const SETTINGS = {
  secret: 'PASTE-THE-SHARED-SECRET-HERE',
  supabaseUrl: 'https://dnjqpcaryfinyicvzkiy.supabase.co',
  anonKey: 'PASTE-THE-PUBLISHABLE-ANON-KEY-HERE'
};
const out = [];
for (const item of $input.all()) {
  const m = item.json || {};
  const hdr = (name) => {
    const direct = m[name] ?? m[name.toLowerCase()] ?? m[name.charAt(0).toUpperCase() + name.slice(1)];
    if (direct) return String(direct);
    const list = (m.headers && Array.isArray(m.headers)) ? m.headers : (m.payload && m.payload.headers) || [];
    const h = list.find(x => String(x.name).toLowerCase() === name.toLowerCase());
    return h ? String(h.value) : '';
  };
  const fromRaw = hdr('from');
  const mm = /^(.*?)\s*<([^>]+)>\s*$/.exec(fromRaw) || [];
  const from_email = (mm[2] || fromRaw).trim().toLowerCase().replace(/^"|"$/g, '');
  const from_name = (mm[1] || '').replace(/^"|"$/g, '').trim();
  const subject = hdr('subject');
  let body = m.textPlain || m.text || '';
  if (!body && (m.textHtml || m.html)) body = String(m.textHtml || m.html).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>(?=\S)/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
  if (!body) body = m.snippet || '';
  // drop quoted history so the timeline shows just the new words
  body = String(body).split(/\r?\n(?=On .+ wrote:)|\r?\n-----Original Message-----|\r?\nFrom: .*\r?\nSent: /)[0].trim();
  if (!from_email) continue;
  out.push({ json: {
    from_email, from_name, subject, body: body.slice(0, 20000),
    thread_id: m.threadId || m.thread_id || null,
    message_id: m.id || m.message_id || null,
    received_at: m.date || m.Date || hdr('date') || new Date().toISOString(),
    supabaseUrl: SETTINGS.supabaseUrl, anonKey: SETTINGS.anonKey, secret: SETTINGS.secret
  }});
}
return out;
